 15→/**
 16→ * Cluster-aware engine that distributes tables and partitions across cluster members.
 17→ *
 18→ * <p>
 19→ * Contract: Wraps a local {@link Engine} instance and adds cluster membership, ownership
 20→ * assignment, and distributed query routing. On {@link #createTable}, creates the table
 21→ * locally and announces it to the cluster. On {@link #getTable}, returns a
 22→ * {@link ClusteredTable} proxy for partitioned tables or delegates to the local engine
 23→ * for locally-owned tables. Listens for membership changes to trigger rebalancing of
 24→ * table and partition ownership.
 25→ *
 26→ * <p>
 27→ * Side effects: Starts membership protocol on build. Modifies ownership assignments
 28→ * on membership changes. Creates and manages {@link ClusteredTable} proxies.
 29→ *
 30→ * <p>
 31→ * Governed by: {@code .decisions/cluster-membership-protocol/adr.md},
 32→ * {@code .decisions/partition-to-node-ownership/adr.md},
 33→ * {@code .decisions/rebalancing-grace-period-strategy/adr.md},
 34→ * {@code .decisions/scatter-gather-query-execution/adr.md},
 35→ * {@code .decisions/discovery-spi-design/adr.md},
 36→ * {@code .decisions/transport-abstraction-design/adr.md}
 37→ */
 38→public final class ClusteredEngine implements Engine {
 39→
 40→    private final Engine localEngine;
 41→    private final MembershipProtocol membership;
 42→    private final RendezvousOwnership ownership;
 43→    private final GracePeriodManager gracePeriodManager;
 44→    private final ClusterTransport transport;
 45→    private final ClusterConfig config;
 46→    private final NodeAddress localAddress;
 47→    private volatile boolean closed;
 48→
 49→    private ClusteredEngine(Builder builder) {
 50→        this.localEngine = Objects.requireNonNull(builder.localEngine, "localEngine");
 51→        this.membership = Objects.requireNonNull(builder.membership, "membership");
 52→        this.ownership = Objects.requireNonNull(builder.ownership, "ownership");
 53→        this.gracePeriodManager = Objects.requireNonNull(builder.gracePeriodManager,
 54→                "gracePeriodManager");
 55→        this.transport = Objects.requireNonNull(builder.transport, "transport");
 56→        this.config = Objects.requireNonNull(builder.config, "config");
 57→        this.localAddress = Objects.requireNonNull(builder.localAddress, "localAddress");
 58→    }
 59→
 60→    /**
 61→     * Returns a new builder for constructing a {@link ClusteredEngine}.
 62→     *
 63→     * @return a new builder; never null
 64→     */
 65→    public static Builder builder() {
 66→        return new Builder();
 67→    }
 68→
 69→    @Override
 70→    public Table createTable(String name, JlsmSchema schema) throws IOException {
 71→        throw new UnsupportedOperationException("Not implemented");
 72→    }
 73→
 74→    @Override
 75→    public Table getTable(String name) throws IOException {
 76→        throw new UnsupportedOperationException("Not implemented");
 77→    }
 78→
 79→    @Override
 80→    public void dropTable(String name) throws IOException {
 81→        throw new UnsupportedOperationException("Not implemented");
 82→    }
 83→
 84→    @Override
 85→    public Collection<TableMetadata> listTables() {
 86→        throw new UnsupportedOperationException("Not implemented");
 87→    }
 88→
 89→    @Override
 90→    public TableMetadata tableMetadata(String name) {
 91→        throw new UnsupportedOperationException("Not implemented");
 92→    }
 93→
 94→    @Override
 95→    public EngineMetrics metrics() {
 96→        throw new UnsupportedOperationException("Not implemented");
 97→    }
 98→
 99→    @Override
100→    public void close() throws IOException {
101→        throw new UnsupportedOperationException("Not implemented");
102→    }
103→
104→    /**
105→     * Builder for {@link ClusteredEngine}.
106→     */
107→    public static final class Builder {
108→
109→        private Engine localEngine;
110→        private MembershipProtocol membership;
111→        private RendezvousOwnership ownership;
112→        private GracePeriodManager gracePeriodManager;
113→        private ClusterTransport transport;
114→        private ClusterConfig config;
115→        private NodeAddress localAddress;
116→
117→        private Builder() {}
118→
119→        public Builder localEngine(Engine localEngine) {
120→            this.localEngine = Objects.requireNonNull(localEngine, "localEngine must not be null");
121→            return this;
122→        }
123→
124→        public Builder membership(MembershipProtocol membership) {
125→            this.membership = Objects.requireNonNull(membership, "membership must not be null");
126→            return this;
127→        }
128→
129→        public Builder ownership(RendezvousOwnership ownership) {
130→            this.ownership = Objects.requireNonNull(ownership, "ownership must not be null");
131→            return this;
132→        }
133→
134→        public Builder gracePeriodManager(GracePeriodManager gracePeriodManager) {
135→            this.gracePeriodManager = Objects.requireNonNull(gracePeriodManager,
136→                    "gracePeriodManager must not be null");
137→            return this;
138→        }
139→
140→        public Builder transport(ClusterTransport transport) {
141→            this.transport = Objects.requireNonNull(transport, "transport must not be null");
142→            return this;
143→        }
144→
145→        public Builder config(ClusterConfig config) {
146→            this.config = Objects.requireNonNull(config, "config must not be null");
147→            return this;
148→        }
149→
150→        public Builder localAddress(NodeAddress localAddress) {
151→            this.localAddress = Objects.requireNonNull(localAddress,
152→                    "localAddress must not be null");
153→            return this;
154→        }
155→
156→        /**
157→         * Builds the clustered engine.
158→         *
159→         * @return a new {@link ClusteredEngine}; never null
160→         */
161→        public ClusteredEngine build() {
162→            return new ClusteredEngine(this);
163→        }
164→    }
165→}
