 15→/**
 16→ * Partition-aware proxy table that scatters queries across remote partition owners.
 17→ *
 18→ * <p>
 19→ * Contract: Implements {@link Table} transparently for partitioned tables in a cluster.
 20→ * Inspects predicates for partition pruning (O(log P) on range boundaries). Scatters
 21→ * sub-queries concurrently via the cluster transport. Gathers results with a streaming
 22→ * k-way merge iterator. Attaches {@link PartialResultMetadata} when some partitions are
 23→ * unavailable. Write operations route to the single partition owner.
 24→ *
 25→ * <p>
 26→ * Side effects: Sends messages via {@link ClusterTransport} to remote partition owners.
 27→ * May return incomplete results if some owners are unavailable.
 28→ *
 29→ * <p>
 30→ * Governed by: {@code .decisions/scatter-gather-query-execution/adr.md}
 31→ */
 32→public final class ClusteredTable implements Table {
 33→
 34→    private final TableMetadata tableMetadata;
 35→    private final ClusterTransport transport;
 36→    private final MembershipProtocol membership;
 37→    private volatile boolean closed;
 38→
 39→    /**
 40→     * Creates a new clustered table proxy.
 41→     *
 42→     * @param tableMetadata the metadata for this table; must not be null
 43→     * @param transport     the cluster transport for remote communication; must not be null
 44→     * @param membership    the membership protocol for resolving partition owners; must not be null
 45→     */
 46→    public ClusteredTable(TableMetadata tableMetadata, ClusterTransport transport,
 47→            MembershipProtocol membership) {
 48→        this.tableMetadata = Objects.requireNonNull(tableMetadata, "tableMetadata must not be null");
 49→        this.transport = Objects.requireNonNull(transport, "transport must not be null");
 50→        this.membership = Objects.requireNonNull(membership, "membership must not be null");
 51→    }
 52→
 53→    @Override
 54→    public void create(String key, JlsmDocument doc) throws IOException {
 55→        throw new UnsupportedOperationException("Not implemented");
 56→    }
 57→
 58→    @Override
 59→    public Optional<JlsmDocument> get(String key) throws IOException {
 60→        throw new UnsupportedOperationException("Not implemented");
 61→    }
 62→
 63→    @Override
 64→    public void update(String key, JlsmDocument doc, UpdateMode mode) throws IOException {
 65→        throw new UnsupportedOperationException("Not implemented");
 66→    }
 67→
 68→    @Override
 69→    public void delete(String key) throws IOException {
 70→        throw new UnsupportedOperationException("Not implemented");
 71→    }
 72→
 73→    @Override
 74→    public void insert(JlsmDocument doc) throws IOException {
 75→        throw new UnsupportedOperationException("Not implemented");
 76→    }
 77→
 78→    @Override
 79→    public TableQuery<String> query() {
 80→        throw new UnsupportedOperationException("Not implemented");
 81→    }
 82→
 83→    @Override
 84→    public Iterator<TableEntry<String>> scan(String fromKey, String toKey) throws IOException {
 85→        throw new UnsupportedOperationException("Not implemented");
 86→    }
 87→
 88→    @Override
 89→    public TableMetadata metadata() {
 90→        return tableMetadata;
 91→    }
 92→
 93→    /**
 94→     * Returns the partial result metadata from the most recent query, or null if none.
 95→     *
 96→     * @return the partial result metadata, or null if the last operation was complete
 97→     */
 98→    public PartialResultMetadata lastPartialResultMetadata() {
 99→        throw new UnsupportedOperationException("Not implemented");
100→    }
101→
102→    @Override
103→    public void close() {
104→        closed = true;
105→    }
106→}
