19→/**
20→ * Remote partition client that communicates with a partition owner via the cluster transport.
21→ *
22→ * <p>
23→ * Contract: Implements {@link PartitionClient} by serializing CRUD and query operations as
24→ * {@code QUERY_REQUEST} messages, sending them to the remote partition owner via
25→ * {@link ClusterTransport#request}, and deserializing the {@code QUERY_RESPONSE}.
26→ *
27→ * <p>
28→ * Side effects: Sends messages via the cluster transport. Blocks on the response future
29→ * with a configurable timeout.
30→ *
31→ * <p>
32→ * Governed by: {@code .decisions/transport-abstraction-design/adr.md}
33→ */
34→public final class RemotePartitionClient implements PartitionClient {
35→
36→    private final PartitionDescriptor descriptor;
37→    private final NodeAddress owner;
38→    private final ClusterTransport transport;
39→    private final NodeAddress localAddress;
40→    private volatile boolean closed;
41→
42→    /**
43→     * Creates a remote partition client.
44→     *
45→     * @param descriptor   the partition descriptor; must not be null
46→     * @param owner        the address of the partition owner; must not be null
47→     * @param transport    the cluster transport; must not be null
48→     * @param localAddress the local node address (for message sender field); must not be null
49→     */
50→    public RemotePartitionClient(PartitionDescriptor descriptor, NodeAddress owner,
51→            ClusterTransport transport, NodeAddress localAddress) {
52→        this.descriptor = Objects.requireNonNull(descriptor, "descriptor must not be null");
53→        this.owner = Objects.requireNonNull(owner, "owner must not be null");
54→        this.transport = Objects.requireNonNull(transport, "transport must not be null");
55→        this.localAddress = Objects.requireNonNull(localAddress, "localAddress must not be null");
56→    }
