64→    public void create(String key, JlsmDocument doc) throws IOException {
65→        throw new UnsupportedOperationException("Not implemented");
66→    }
67→
68→    @Override
69→    public Optional<JlsmDocument> get(String key) throws IOException {
70→        throw new UnsupportedOperationException("Not implemented");
71→    }
72→
73→    @Override
74→    public void update(String key, JlsmDocument doc, UpdateMode mode) throws IOException {
75→        throw new UnsupportedOperationException("Not implemented");
76→    }
77→
78→    @Override
79→    public void delete(String key) throws IOException {
80→        throw new UnsupportedOperationException("Not implemented");
81→    }
