 1→package jlsm.engine.cluster;
 2→
 3→import java.util.Objects;
 4→
 5→/**
 6→ * A typed message exchanged between cluster nodes over the {@link ClusterTransport}.
 7→ *
 8→ * <p>
 9→ * Contract: Immutable value type encapsulating a message with its type, sender identity,
10→ * sequence number for deduplication/ordering, and an opaque payload. The payload format
11→ * is determined by the {@link MessageType}.
12→ *
13→ * <p>
14→ * Governed by: {@code .decisions/transport-abstraction-design/adr.md}
15→ *
16→ * @param type           the message type; must not be null
17→ * @param sender         the address of the sending node; must not be null
18→ * @param sequenceNumber monotonically increasing sequence for ordering; must be non-negative
19→ * @param payload        the message payload bytes; must not be null (may be empty)
20→ */
21→public record Message(MessageType type, NodeAddress sender, long sequenceNumber, byte[] payload) {
22→
23→    public Message {
24→        Objects.requireNonNull(type, "type must not be null");
25→        Objects.requireNonNull(sender, "sender must not be null");
26→        Objects.requireNonNull(payload, "payload must not be null");
27→        if (sequenceNumber < 0) {
28→            throw new IllegalArgumentException(
29→                    "sequenceNumber must be non-negative, got: " + sequenceNumber);
30→        }
31→        payload = payload.clone();
32→    }
33→
34→    /**
35→     * Returns a defensive copy of the payload.
36→     *
37→     * @return a copy of the payload bytes; never null
38→     */
39→    @Override
40→    public byte[] payload() {
41→        return payload.clone();
42→    }
43→}
44→

 1→package jlsm.engine.cluster;
 2→
 3→import java.util.Objects;
 4→
 5→/**
 6→ * Identity and network address of a cluster node.
 7→ *
 8→ * <p>
 9→ * Contract: Immutable value type uniquely identifying a node. The {@code nodeId} is the primary
10→ * identity; {@code host} and {@code port} describe the network endpoint. Two {@code NodeAddress}
11→ * instances are equal if and only if all three fields match.
12→ *
13→ * <p>
14→ * Governed by: {@code .decisions/transport-abstraction-design/adr.md}
15→ *
16→ * @param nodeId unique identifier for the node; must not be null or empty
17→ * @param host   the hostname or IP address; must not be null or empty
18→ * @param port   the port number; must be in range [1, 65535]
19→ */
20→public record NodeAddress(String nodeId, String host, int port) {
21→
22→    public NodeAddress {
23→        Objects.requireNonNull(nodeId, "nodeId must not be null");
24→        Objects.requireNonNull(host, "host must not be null");
25→        if (nodeId.isEmpty()) {
26→            throw new IllegalArgumentException("nodeId must not be empty");
27→        }
28→        if (host.isEmpty()) {
29→            throw new IllegalArgumentException("host must not be empty");
30→        }
31→        if (port < 1 || port > 65535) {
32→            throw new IllegalArgumentException("port must be in range [1, 65535], got: " + port);
33→        }
34→    }
35→}
