 1→package jlsm.engine.cluster;
 2→
 3→import java.util.Objects;
 4→import java.util.Set;
 5→
 6→/**
 7→ * Metadata describing the completeness of a scatter-gather query result.
 8→ *
 9→ * <p>
10→ * Contract: Immutable value type attached to query results from partitioned tables. Tracks
11→ * which partitions were unavailable during query execution, allowing callers to determine
12→ * whether the result set is complete.
13→ *
14→ * <p>
15→ * Governed by: {@code .decisions/scatter-gather-query-execution/adr.md}
16→ *
17→ * @param unavailablePartitions the set of partition identifiers that could not be reached;
18→ *                              must not be null (empty if all partitions responded)
19→ * @param isComplete            {@code true} if all partitions contributed to the result
20→ */
21→public record PartialResultMetadata(Set<String> unavailablePartitions, boolean isComplete) {
22→
23→    public PartialResultMetadata {
24→        Objects.requireNonNull(unavailablePartitions, "unavailablePartitions must not be null");
25→        unavailablePartitions = Set.copyOf(unavailablePartitions);
26→    }
27→}
