  1→package jlsm.engine.cluster;
  2→
  3→import java.time.Instant;
  4→import java.util.Objects;
  5→import java.util.Set;
  6→
  7→/**
  8→ * An immutable snapshot of the cluster membership at a specific epoch.
  9→ *
 10→ * <p>
 11→ * Contract: Captures the set of known members, the view epoch (monotonically increasing),
 12→ * and the timestamp when this view was created. Provides convenience methods for querying
 13→ * membership state. Comparable by epoch for ordering views chronologically.
 14→ *
 15→ * <p>
 16→ * Governed by: {@code .decisions/cluster-membership-protocol/adr.md}
 17→ */
 18→public final class MembershipView implements Comparable<MembershipView> {
 19→
 20→    private final long epoch;
 21→    private final Set<Member> members;
 22→    private final Instant timestamp;
 23→
 24→    /**
 25→     * Creates a new membership view.
 26→     *
 27→     * @param epoch     the view epoch; must be non-negative
 28→     * @param members   the set of members in this view; must not be null
 29→     * @param timestamp the instant this view was created; must not be null
 30→     */
 31→    public MembershipView(long epoch, Set<Member> members, Instant timestamp) {
 32→        if (epoch < 0) {
 33→            throw new IllegalArgumentException("epoch must be non-negative, got: " + epoch);
 34→        }
 35→        Objects.requireNonNull(members, "members must not be null");
 36→        Objects.requireNonNull(timestamp, "timestamp must not be null");
 37→        this.epoch = epoch;
 38→        this.members = Set.copyOf(members);
 39→        this.timestamp = timestamp;
 40→    }
 41→
 42→    /**
 43→     * Returns the view epoch.
 44→     *
 45→     * @return the epoch; always non-negative
 46→     */
 47→    public long epoch() {
 48→        return epoch;
 49→    }
 50→
 51→    /**
 52→     * Returns the immutable set of members in this view.
 53→     *
 54→     * @return the members; never null
 55→     */
 56→    public Set<Member> members() {
 57→        return members;
 58→    }
 59→
 60→    /**
 61→     * Returns the timestamp when this view was created.
 62→     *
 63→     * @return the timestamp; never null
 64→     */
 65→    public Instant timestamp() {
 66→        return timestamp;
 67→    }
 68→
 69→    /**
 70→     * Returns the number of members in {@link MemberState#ALIVE} state.
 71→     *
 72→     * @return the count of live members
 73→     */
 74→    public int liveMemberCount() {
 75→        int count = 0;
 76→        for (Member m : members) {
 77→            if (m.state() == MemberState.ALIVE) {
 78→                count++;
 79→            }
 80→        }
 81→        return count;
 82→    }
 83→
 84→    /**
 85→     * Returns whether the given address is a member of this view (in any state).
 86→     *
 87→     * @param address the node address to check; must not be null
 88→     * @return {@code true} if the address is present in this view
 89→     */
 90→    public boolean isMember(NodeAddress address) {
 91→        Objects.requireNonNull(address, "address must not be null");
 92→        for (Member m : members) {
 93→            if (m.address().equals(address)) {
 94→                return true;
 95→            }
 96→        }
 97→        return false;
 98→    }
 99→
100→    /**
101→     * Returns whether the live members form a quorum at the given percentage threshold.
102→     *
103→     * @param quorumPercent the required percentage of live members; must be in [1, 100]
104→     * @return {@code true} if the live member count meets or exceeds the quorum threshold
105→     */
106→    public boolean hasQuorum(int quorumPercent) {
107→        if (quorumPercent < 1 || quorumPercent > 100) {
108→            throw new IllegalArgumentException(
109→                    "quorumPercent must be in [1, 100], got: " + quorumPercent);
110→        }
111→        if (members.isEmpty()) {
112→            return false;
113→        }
114→        final int liveCount = liveMemberCount();
115→        final int totalCount = members.size();
116→        return (liveCount * 100) >= (quorumPercent * totalCount);
117→    }
118→
119→    @Override
120→    public int compareTo(MembershipView other) {
121→        return Long.compare(this.epoch, other.epoch);
122→    }
123→
124→    @Override
125→    public boolean equals(Object o) {
126→        if (this == o) return true;
127→        if (!(o instanceof MembershipView that)) return false;
128→        return epoch == that.epoch && members.equals(that.members)
129→                && timestamp.equals(that.timestamp);
130→    }
131→
132→    @Override
133→    public int hashCode() {
134→        return Objects.hash(epoch, members, timestamp);
135→    }
136→
137→    @Override
138→    public String toString() {
139→        return "MembershipView[epoch=" + epoch + ", members=" + members.size()
140→                + ", timestamp=" + timestamp + "]";
141→    }
142→}
143→

  1→package jlsm.engine.cluster.internal;
  2→
  3→import jlsm.engine.cluster.ClusterTransport;
  4→import jlsm.engine.cluster.Message;
  5→import jlsm.engine.cluster.MessageHandler;
  6→import jlsm.engine.cluster.MessageType;
  7→import jlsm.engine.cluster.NodeAddress;
