  1→package jlsm.engine.cluster.internal;
  2→
  3→import jlsm.engine.cluster.Member;
  4→import jlsm.engine.cluster.MemberState;
  5→import jlsm.engine.cluster.MembershipView;
  6→import jlsm.engine.cluster.NodeAddress;
  7→
  8→import java.nio.charset.StandardCharsets;
  9→import java.util.ArrayList;
 10→import java.util.Comparator;
 11→import java.util.List;
 12→import java.util.Objects;
 13→import java.util.concurrent.ConcurrentHashMap;
 14→
 15→/**
 16→ * Deterministic partition-to-node ownership via Rendezvous (Highest Random Weight) hashing.
 17→ *
 18→ * <p>
 19→ * Contract: Pure function of (identifier, membership view). Given the same view, all nodes
 20→ * compute the same ownership assignment. For each table or partition ID, computes
 21→ * hash(id, node_id) for all live nodes in the view and assigns to the node with the
 22→ * highest weight. Results are cached keyed on view epoch to avoid redundant computation.
 23→ *
 24→ * <p>
 25→ * Thread-safe: uses concurrent cache and pure computations.
 26→ *
 27→ * <p>
 28→ * Governed by: {@code .decisions/partition-to-node-ownership/adr.md}
 29→ */
 30→public final class RendezvousOwnership {
 31→
 32→    private final ConcurrentHashMap<Long, ConcurrentHashMap<String, NodeAddress>> cache =
 33→            new ConcurrentHashMap<>();
 34→
 35→    /**
 36→     * Assigns a single owner for the given identifier within the current membership view.
 37→     *
 38→     * @param id   the table or partition identifier; must not be null or empty
 39→     * @param view the current membership view; must not be null
 40→     * @return the owning node's address; never null
 41→     * @throws IllegalStateException if the view contains no live members
 42→     */
 43→    public NodeAddress assignOwner(String id, MembershipView view) {
 44→        Objects.requireNonNull(id, "id must not be null");
 45→        Objects.requireNonNull(view, "view must not be null");
 46→        if (id.isEmpty()) {
 47→            throw new IllegalArgumentException("id must not be empty");
 48→        }
 49→
 50→        final ConcurrentHashMap<String, NodeAddress> epochCache =
 51→                cache.computeIfAbsent(view.epoch(), _ -> new ConcurrentHashMap<>());
 52→
 53→        final NodeAddress cached = epochCache.get(id);
 54→        if (cached != null) {
 55→            return cached;
 56→        }
 57→
 58→        final List<NodeAddress> ranked = computeRankedOwners(id, view);
 59→        assert !ranked.isEmpty() : "ranked list must not be empty after live-member check";
 60→
 61→        final NodeAddress owner = ranked.getFirst();
 62→        epochCache.put(id, owner);
 63→        return owner;
 64→    }
 65→
 66→    /**
 67→     * Assigns multiple owners (for future replication) ranked by weight.
 68→     *
 69→     * @param id       the table or partition identifier; must not be null or empty
 70→     * @param view     the current membership view; must not be null
 71→     * @param replicas the number of owners to assign; must be >= 1
 72→     * @return a list of node addresses ranked by weight, up to {@code replicas} or the number
 73→     *         of live members, whichever is smaller; never null or empty
 74→     * @throws IllegalStateException if the view contains no live members
 75→     */
 76→    public List<NodeAddress> assignOwners(String id, MembershipView view, int replicas) {
 77→        Objects.requireNonNull(id, "id must not be null");
 78→        Objects.requireNonNull(view, "view must not be null");
 79→        if (id.isEmpty()) {
 80→            throw new IllegalArgumentException("id must not be empty");
 81→        }
 82→        if (replicas < 1) {
 83→            throw new IllegalArgumentException("replicas must be >= 1, got: " + replicas);
 84→        }
 85→
 86→        final List<NodeAddress> ranked = computeRankedOwners(id, view);
 87→        assert !ranked.isEmpty() : "ranked list must not be empty after live-member check";
 88→
 89→        final int count = Math.min(replicas, ranked.size());
 90→        return List.copyOf(ranked.subList(0, count));
 91→    }
 92→
 93→    /**
 94→     * Invalidates cached assignments for views older than the given epoch.
 95→     *
 96→     * @param currentEpoch the current epoch; entries for older epochs are evicted
 97→     */
 98→    public void evictBefore(long currentEpoch) {
 99→        cache.keySet().removeIf(epoch -> epoch < currentEpoch);
100→    }
101→
102→    /**
103→     * Computes the full ranking of live members for the given id, sorted by descending
104→     * HRW weight. Ties are broken by nodeId for determinism.
105→     */
106→    private List<NodeAddress> computeRankedOwners(String id, MembershipView view) {
107→        final List<WeightedNode> weighted = new ArrayList<>();
108→        final byte[] idBytes = id.getBytes(StandardCharsets.UTF_8);
109→
110→        for (Member member : view.members()) {
111→            if (member.state() != MemberState.ALIVE) {
112→                continue;
113→            }
114→            final byte[] nodeBytes = member.address().nodeId().getBytes(StandardCharsets.UTF_8);
115→            final long weight = hrwHash(idBytes, nodeBytes);
116→            weighted.add(new WeightedNode(member.address(), weight));
117→        }
118→
119→        if (weighted.isEmpty()) {
120→            throw new IllegalStateException("No live members in the membership view");
121→        }
122→
123→        // Sort by weight descending, then by nodeId ascending for deterministic tie-breaking
124→        weighted.sort(Comparator.comparingLong(WeightedNode::weight).reversed()
125→                .thenComparing(wn -> wn.address().nodeId()));
126→
127→        final List<NodeAddress> result = new ArrayList<>(weighted.size());
128→        for (WeightedNode wn : weighted) {
129→            result.add(wn.address());
130→        }
131→        assert result.size() == weighted.size() : "result size must match weighted size";
132→        return result;
133→    }
134→
135→    /**
136→     * Computes a hash weight for the (id, nodeId) pair using a SipHash-inspired mixing
137→     * function. The result is deterministic and uniformly distributed.
138→     */
139→    private static long hrwHash(byte[] idBytes, byte[] nodeBytes) {
140→        // Combine id and nodeId bytes with a simple but effective mixing strategy.
141→        // Use FNV-1a variant for fast, well-distributed hashing.
142→        long hash = 0xcbf29ce484222325L; // FNV offset basis
143→        final long prime = 0x100000001b3L;  // FNV prime
144→
145→        for (byte b : idBytes) {
146→            hash ^= (b & 0xffL);
147→            hash *= prime;
148→        }
149→        // Separator to prevent collisions between ("ab","cd") and ("abc","d")
150→        hash ^= 0xffL;
151→        hash *= prime;
152→
153→        for (byte b : nodeBytes) {
154→            hash ^= (b & 0xffL);
155→            hash *= prime;
156→        }
157→
158→        // Finalizer mix (Stafford variant 13)
159→        hash ^= (hash >>> 30);
160→        hash *= 0xbf58476d1ce4e5b9L;
161→        hash ^= (hash >>> 27);
162→        hash *= 0x94d049bb133111ebL;
163→        hash ^= (hash >>> 31);
164→
165→        return hash;
166→    }
167→
168→    private record WeightedNode(NodeAddress address, long weight) {}
169→}
