  1→package jlsm.table;
  2→
  3→import jlsm.table.internal.RangeMap;
  4→import jlsm.table.internal.ResultMerger;
  5→
  6→import java.io.Closeable;
  7→import java.io.IOException;
  8→import java.lang.foreign.MemorySegment;
  9→import java.nio.charset.StandardCharsets;
 10→import java.util.ArrayList;
 11→import java.util.Iterator;
 12→import java.util.LinkedHashMap;
 13→import java.util.List;
 14→import java.util.Map;
 15→import java.util.Objects;
 16→import java.util.Optional;
 17→import java.util.function.Function;
 18→
 19→/**
 20→ * Coordinator for a range-partitioned table.
 21→ *
 22→ * <p>
 23→ * Contract: Routes key-based CRUD to the correct partition via O(log P) range map lookup. Executes
 24→ * scatter-gather for multi-partition queries (vector, full-text, combined) and merges results. Each
 25→ * partition is accessed through a {@link PartitionClient}, allowing future remote implementations
 26→ * without changing the coordinator.
 27→ *
 28→ * <p>
 29→ * Governed by: .decisions/table-partitioning/adr.md — range partitioning with per-partition
 30→ * co-located indices.
 31→ */
 32→public final class PartitionedTable implements Closeable {
 33→
 34→    private final PartitionConfig config;
 35→    private final RangeMap rangeMap;
 36→    // Ordered map: descriptor id → client (insertion order matches config order)
 37→    private final Map<Long, PartitionClient> clients;
 38→
 39→    private PartitionedTable(PartitionConfig config, RangeMap rangeMap,
 40→            Map<Long, PartitionClient> clients) {
 41→        assert config != null : "config must not be null";
 42→        assert rangeMap != null : "rangeMap must not be null";
 43→        assert clients != null : "clients must not be null";
 44→        assert !clients.isEmpty() : "clients must not be empty";
 45→        this.config = config;
 46→        this.rangeMap = rangeMap;
 47→        this.clients = clients;
 48→    }
 49→
 50→    /**
 51→     * Returns a builder for constructing a partitioned table.
 52→     *
 53→     * @return a new builder
 54→     */
 55→    public static Builder builder() {
 56→        return new Builder();
 57→    }
 58→
 59→    /**
 60→     * Creates a document, routing to the correct partition by key.
 61→     *
 62→     * @param key the document key
 63→     * @param doc the document to create
 64→     * @throws IOException if the write fails
 65→     * @throws DuplicateKeyException if the key already exists
 66→     */
 67→    public void create(String key, JlsmDocument doc) throws IOException {
 68→        Objects.requireNonNull(key, "key must not be null");
 69→        Objects.requireNonNull(doc, "doc must not be null");
 70→        final PartitionClient client = routeKey(key);
 71→        client.create(key, doc);
 72→    }
 73→
 74→    /**
 75→     * Retrieves a document by key, routing to the correct partition.
 76→     *
 77→     * @param key the document key
 78→     * @return the document, or empty if not found
 79→     * @throws IOException if the read fails
 80→     */
 81→    public Optional<JlsmDocument> get(String key) throws IOException {
 82→        Objects.requireNonNull(key, "key must not be null");
 83→        final PartitionClient client = routeKey(key);
 84→        return client.get(key);
 85→    }
 86→
 87→    /**
 88→     * Updates a document, routing to the correct partition by key.
 89→     *
 90→     * @param key the document key
 91→     * @param doc the updated document
 92→     * @param mode replace or patch
 93→     * @throws IOException if the write fails
 94→     */
 95→    public void update(String key, JlsmDocument doc, UpdateMode mode) throws IOException {
 96→        Objects.requireNonNull(key, "key must not be null");
 97→        Objects.requireNonNull(doc, "doc must not be null");
 98→        Objects.requireNonNull(mode, "mode must not be null");
 99→        final PartitionClient client = routeKey(key);
100→        client.update(key, doc, mode);
101→    }
102→
103→    /**
104→     * Deletes a document, routing to the correct partition by key.
105→     *
106→     * @param key the document key
107→     * @throws IOException if the write fails
108→     */
109→    public void delete(String key) throws IOException {
110→        Objects.requireNonNull(key, "key must not be null");
111→        final PartitionClient client = routeKey(key);
112→        client.delete(key);
113→    }
114→
115→    /**
116→     * Returns entries across partitions within the given key range, merged in key order.
117→     *
118→     * <p>
119→     * Routes to the minimal set of overlapping partitions and merges their iterators.
120→     *
121→     * @param fromKey inclusive lower bound
122→     * @param toKey exclusive upper bound
123→     * @return iterator over matching entries in key order
124→     * @throws IOException if any partition read fails
125→     */
126→    public Iterator<TableEntry<String>> getRange(String fromKey, String toKey) throws IOException {
127→        Objects.requireNonNull(fromKey, "fromKey must not be null");
128→        Objects.requireNonNull(toKey, "toKey must not be null");
129→        final MemorySegment fromSeg = toSegment(fromKey);
130→        final MemorySegment toSeg = toSegment(toKey);
131→        final List<PartitionDescriptor> overlapping = rangeMap.overlapping(fromSeg, toSeg);
132→        assert !overlapping.isEmpty() || true
133→                : "overlapping may be empty for non-overlapping range";
134→
135→        final List<Iterator<TableEntry<String>>> iterators = new ArrayList<>(overlapping.size());
136→        for (final PartitionDescriptor desc : overlapping) {
137→            final PartitionClient client = clients.get(desc.id());
138→            assert client != null : "no client found for descriptor id " + desc.id();
139→            iterators.add(client.getRange(fromKey, toKey));
140→        }
141→        return ResultMerger.mergeOrdered(iterators);
142→    }
143→
144→    /**
145→     * Executes a query across all relevant partitions and merges results.
146→     *
147→     * <p>
148→     * Per-partition predicate execution is not yet implemented — this method throws
149→     * {@link UnsupportedOperationException} until {@code InProcessPartitionClient.query()} is
150→     * implemented in a future work unit.
151→     *
152→     * @param predicate the query predicate
153→     * @param limit maximum results
154→     * @return scored results merged across partitions
155→     * @throws IOException if any partition query fails
156→     * @throws UnsupportedOperationException always — per-partition predicate execution is not yet
157→     *             implemented
158→     */
159→    public List<ScoredEntry<String>> query(Predicate predicate, int limit) throws IOException {
160→        Objects.requireNonNull(predicate, "predicate must not be null");
161→        if (limit <= 0) {
162→            throw new IllegalArgumentException("limit must be positive, got: " + limit);
163→        }
164→        throw new UnsupportedOperationException(
165→                "per-partition predicate execution is not yet implemented; "
166→                        + "InProcessPartitionClient.query() will be wired in a future work unit");
167→    }
168→
169→    /**
170→     * Returns the partition configuration for this table.
171→     *
172→     * @return the partition config
173→     */
174→    public PartitionConfig config() {
175→        return config;
176→    }
177→
178→    /**
179→     * Closes all partition clients. Uses the deferred close pattern: all clients are closed even if
180→     * one or more throw, and exceptions are accumulated. If any client fails to close, the first
181→     * exception is thrown with remaining exceptions added as suppressed.
182→     *
183→     * @throws IOException if any partition client fails to close
184→     */
185→    @Override
186→    public void close() throws IOException {
187→        IOException firstException = null;
188→        for (final PartitionClient client : clients.values()) {
189→            try {
190→                client.close();
191→            } catch (final IOException e) {
192→                if (firstException == null) {
193→                    firstException = e;
194→                } else {
195→                    firstException.addSuppressed(e);
196→                }
197→            }
198→        }
199→        if (firstException != null) {
200→            throw firstException;
201→        }
202→    }
203→
204→    // -------------------------------------------------------------------------
205→    // Internal helpers
206→    // -------------------------------------------------------------------------
207→
208→    /**
209→     * Routes the given string key to its owning partition client.
210→     *
211→     * @param key the string key
212→     * @return the owning partition client
213→     * @throws IllegalArgumentException if the key falls outside all partition ranges
214→     */
215→    private PartitionClient routeKey(String key) {
216→        assert key != null : "key must not be null";
217→        final MemorySegment keySeg = toSegment(key);
218→        final PartitionDescriptor desc = rangeMap.routeKey(keySeg);
219→        final PartitionClient client = clients.get(desc.id());
220→        assert client != null : "no client registered for descriptor id " + desc.id();
221→        return client;
222→    }
223→
224→    /**
225→     * Converts a string key to a {@link MemorySegment} in UTF-8 encoding for RangeMap routing.
226→     *
227→     * @param key the string key
228→     * @return the key as a MemorySegment
229→     */
230→    private static MemorySegment toSegment(String key) {
231→        assert key != null : "key must not be null";
232→        return MemorySegment.ofArray(key.getBytes(StandardCharsets.UTF_8));
233→    }
234→
235→    // -------------------------------------------------------------------------
236→    // Builder
237→    // -------------------------------------------------------------------------
238→
239→    /**
240→     * Builder for {@link PartitionedTable}.
241→     */
242→    public static final class Builder {
243→
244→        private PartitionConfig config;
245→        private JlsmSchema schema;
246→        private Function<PartitionDescriptor, PartitionClient> factory;
247→
248→        private Builder() {
249→        }
250→
251→        /**
252→         * Sets the partition configuration.
253→         *
254→         * @param config the partition layout
255→         * @return this builder
256→         */
257→        public Builder partitionConfig(PartitionConfig config) {
258→            this.config = Objects.requireNonNull(config, "config must not be null");
259→            return this;
260→        }
261→
262→        /**
263→         * Sets the schema shared by all partitions.
264→         *
265→         * @param schema the document schema
266→         * @return this builder
267→         */
268→        public Builder schema(JlsmSchema schema) {
269→            this.schema = schema; // optional — may be null
270→            return this;
271→        }
272→
273→        /**
274→         * Sets the factory for creating partition clients. Called once per partition during build.
275→         *
276→         * @param factory function from PartitionDescriptor to PartitionClient
277→         * @return this builder
278→         */
279→        public Builder partitionClientFactory(
280→                Function<PartitionDescriptor, PartitionClient> factory) {
281→            this.factory = Objects.requireNonNull(factory, "factory must not be null");
282→            return this;
283→        }
284→
285→        /**
286→         * Builds the partitioned table.
287→         *
288→         * <p>
289→         * Invokes the partition client factory once per descriptor in the configuration. All
290→         * created clients are owned by the returned {@link PartitionedTable} and closed when the
291→         * table is closed.
292→         *
293→         * @return the configured partitioned table
294→         * @throws IOException if any partition client fails to initialize
295→         * @throws IllegalStateException if partitionConfig or partitionClientFactory is not set
296→         */
297→        public PartitionedTable build() throws IOException {
298→            if (config == null) {
299→                throw new IllegalStateException(
300→                        "partitionConfig must be set before calling build()");
301→            }
302→            if (factory == null) {
303→                throw new IllegalStateException(
304→                        "partitionClientFactory must be set before calling build()");
305→            }
306→
307→            final RangeMap rangeMap = new RangeMap(config);
308→
309→            // Build clients in config order, using LinkedHashMap to preserve insertion order
310→            final Map<Long, PartitionClient> clients = new LinkedHashMap<>();
311→            for (final PartitionDescriptor desc : config.descriptors()) {
312→                final PartitionClient client = factory.apply(desc);
313→                Objects.requireNonNull(client,
314→                        "partitionClientFactory returned null for descriptor id " + desc.id());
315→                clients.put(desc.id(), client);
316→            }
317→
318→            assert clients.size() == config.partitionCount()
319→                    : "client count must match partition count";
320→            return new PartitionedTable(config, rangeMap, clients);
321→        }
322→    }
323→}
