 1→package jlsm.engine;
 2→
 3→import java.util.Map;
 4→import java.util.Objects;
 5→
 6→/**
 7→ * A snapshot of engine-wide handle counts and statistics.
 8→ *
 9→ * <p>
10→ * Governed by: {@code .decisions/engine-api-surface-design/adr.md}
11→ *
12→ * @param tableCount the number of registered tables
13→ * @param totalOpenHandles the total number of open table handles across all tables
14→ * @param handlesPerTable open handle count per table name; never null
15→ * @param handlesPerSourcePerTable open handle count per source per table; never null
16→ */
17→public record EngineMetrics(int tableCount, int totalOpenHandles,
18→        Map<String, Integer> handlesPerTable,
19→        Map<String, Map<String, Integer>> handlesPerSourcePerTable) {
20→
21→    public EngineMetrics {
22→        assert tableCount >= 0 : "tableCount must be non-negative";
23→        assert totalOpenHandles >= 0 : "totalOpenHandles must be non-negative";
24→        Objects.requireNonNull(handlesPerTable, "handlesPerTable must not be null");
25→        Objects.requireNonNull(handlesPerSourcePerTable,
26→                "handlesPerSourcePerTable must not be null");
