  5→import java.time.Duration;
  6→import java.time.Instant;
  7→import java.util.HashSet;
  8→import java.util.Objects;
  9→import java.util.Set;
 10→import java.util.concurrent.ConcurrentHashMap;
 11→
 12→/**
 13→ * Tracks departed nodes and manages the grace period before permanent removal.
 14→ *
 15→ * <p>
 16→ * Contract: Records node departures with timestamps. A departed node is considered in
 17→ * grace period if the configured duration has not elapsed since departure. After grace
 18→ * period expiry, the departure is permanent. If a node returns during grace, its
 19→ * departure record is cleared. Grace period controls cleanup timing, not ownership
 20→ * assignment — partitions are eagerly reassigned on departure.
 21→ *
 22→ * <p>
 23→ * Thread-safe: uses concurrent data structures.
 24→ *
 25→ * <p>
 26→ * Governed by: {@code .decisions/rebalancing-grace-period-strategy/adr.md}
 27→ */
 28→public final class GracePeriodManager {
 29→
 30→    private final Duration gracePeriod;
 31→    private final ConcurrentHashMap<NodeAddress, Instant> departures = new ConcurrentHashMap<>();
 32→
 33→    /**
 34→     * Creates a grace period manager with the specified duration.
 35→     *
 36→     * @param gracePeriod the grace period duration; must not be null and must be positive
 37→     */
 38→    public GracePeriodManager(Duration gracePeriod) {
 39→        Objects.requireNonNull(gracePeriod, "gracePeriod must not be null");
 40→        if (gracePeriod.isNegative() || gracePeriod.isZero()) {
 41→            throw new IllegalArgumentException("gracePeriod must be positive");
 42→        }
 43→        this.gracePeriod = gracePeriod;
 44→    }
 45→
 46→    /**
 47→     * Records the departure of a node at the given time.
 48→     *
 49→     * @param node       the departed node's address; must not be null
 50→     * @param departedAt the instant of departure; must not be null
 51→     */
 52→    public void recordDeparture(NodeAddress node, Instant departedAt) {
 53→        Objects.requireNonNull(node, "node must not be null");
 54→        Objects.requireNonNull(departedAt, "departedAt must not be null");
 55→        departures.put(node, departedAt);
 56→    }
 57→
 58→    /**
 59→     * Returns whether the given node is currently in its grace period.
 60→     *
 61→     * @param node the node address to check; must not be null
 62→     * @return {@code true} if the node departed and the grace period has not expired
 63→     */
 64→    public boolean isInGracePeriod(NodeAddress node) {
 65→        Objects.requireNonNull(node, "node must not be null");
 66→        final Instant departedAt = departures.get(node);
 67→        if (departedAt == null) {
 68→            return false;
 69→        }
 70→        final Instant expiry = departedAt.plus(gracePeriod);
 71→        return Instant.now().isBefore(expiry);
 72→    }
 73→
 74→    /**
 75→     * Returns the set of nodes whose grace period has expired.
 76→     *
 77→     * @return a set of node addresses with expired grace periods; never null
 78→     */
 79→    public Set<NodeAddress> expiredDepartures() {
 80→        final Instant now = Instant.now();
 81→        final Set<NodeAddress> expired = new HashSet<>();
 82→        for (var entry : departures.entrySet()) {
 83→            final Instant expiry = entry.getValue().plus(gracePeriod);
 84→            assert expiry != null : "expiry must not be null";
 85→            if (!now.isBefore(expiry)) {
 86→                expired.add(entry.getKey());
 87→            }
 88→        }
 89→        return expired;
 90→    }
 91→
 92→    /**
 93→     * Records the return of a previously departed node, clearing its departure record.
 94→     *
 95→     * @param node the returning node's address; must not be null
 96→     */
 97→    public void recordReturn(NodeAddress node) {
 98→        Objects.requireNonNull(node, "node must not be null");
 99→        departures.remove(node);
100→    }
101→}
