    // --- Helper methods ---

    private ClusteredEngine buildEngine(Engine localEngine) {
        return ClusteredEngine.builder()
                .localEngine(localEngine)
                .membership(membershipA)
                .ownership(ownership)
                .gracePeriodManager(gracePeriod)
                .transport(transportA)
                .config(config)
                .localAddress(NODE_A)
                .build();
    }

    private static StubEngine stubEngine() {
        return new StubEngine();
    }

    // --- Stub implementations ---

    /**
     * Stub MembershipProtocol for testing.
     */
    private static final class StubMembershipProtocol implements MembershipProtocol {
        final List<MembershipListener> listeners = new CopyOnWriteArrayList<>();
        private volatile MembershipView view = new MembershipView(0, Set.of(), NOW);
        volatile boolean started;
        volatile boolean left;
        volatile boolean closed;

        @Override
        public void start(List<NodeAddress> seeds) {
            started = true;
        }

        @Override
        public MembershipView currentView() {
            return view;
        }

        void setView(MembershipView newView) {
            final MembershipView old = this.view;
            this.view = newView;
            for (MembershipListener l : listeners) {
                l.onViewChanged(old, newView);
            }
        }

        @Override
        public void addListener(MembershipListener listener) {
            listeners.add(listener);
        }

        @Override
        public void leave() {
            left = true;
        }

        @Override
        public void close() {
            closed = true;
        }
    }

    /**
     * Minimal stub engine that tracks method calls.
     */
    private static final class StubEngine implements Engine {
        final List<String> createdTables = new CopyOnWriteArrayList<>();
        final List<String> droppedTables = new CopyOnWriteArrayList<>();
        private final java.util.concurrent.ConcurrentHashMap<String, TableMetadata> tables =
                new java.util.concurrent.ConcurrentHashMap<>();
        volatile boolean closed;

        @Override
        public Table createTable(String name, JlsmSchema schema) throws IOException {
            if (tables.containsKey(name)) {
                throw new IOException("Table already exists: " + name);
            }
            final TableMetadata meta = new TableMetadata(name, schema, NOW,
                    TableMetadata.TableState.READY);
            tables.put(name, meta);
            createdTables.add(name);
            return new StubTable(meta);
        }

        @Override
        public Table getTable(String name) throws IOException {
            final TableMetadata meta = tables.get(name);
            if (meta == null) {
                throw new IOException("Table does not exist: " + name);
            }
            return new StubTable(meta);
        }

        @Override
        public void dropTable(String name) throws IOException {
            if (tables.remove(name) == null) {
                throw new IOException("Table does not exist: " + name);
            }
            droppedTables.add(name);
        }

        @Override
        public Collection<TableMetadata> listTables() {
            return List.copyOf(tables.values());
        }

        @Override
        public TableMetadata tableMetadata(String name) {
            return tables.get(name);
        }

        @Override
        public EngineMetrics metrics() {
            return new EngineMetrics(tables.size(), 0, Map.of(), Map.of());
        }

        @Override
        public void close() {
            closed = true;
        }
    }

    /**
     * Minimal stub table for testing engine delegation.
     */
    private static final class StubTable implements Table {
        private final TableMetadata metadata;

        StubTable(TableMetadata metadata) {
            this.metadata = metadata;
        }

        @Override
        public void create(String key, jlsm.table.JlsmDocument doc) {
        }

        @Override
        public java.util.Optional<jlsm.table.JlsmDocument> get(String key) {
            return java.util.Optional.empty();
        }

        @Override
        public void update(String key, jlsm.table.JlsmDocument doc, jlsm.table.UpdateMode mode) {
        }

        @Override
        public void delete(String key) {
        }

        @Override
        public void insert(jlsm.table.JlsmDocument doc) {
        }

        @Override
        public jlsm.table.TableQuery<String> query() {
            throw new UnsupportedOperationException("Not implemented");
        }

        @Override
        public java.util.Iterator<jlsm.table.TableEntry<String>> scan(String from, String to) {
            return java.util.Collections.emptyIterator();
        }

        @Override
        public TableMetadata metadata() {
            return metadata;
        }

        @Override
        public void close() {
        }
    }
}

package jlsm.engine.cluster;

import jlsm.engine.TableMetadata;
import jlsm.engine.cluster.internal.InJvmTransport;
import jlsm.engine.cluster.internal.RemotePartitionClient;
import jlsm.engine.cluster.internal.RendezvousOwnership;
import jlsm.table.FieldType;
import jlsm.table.JlsmDocument;
import jlsm.table.JlsmSchema;
import jlsm.table.PartitionDescriptor;
import jlsm.table.TableEntry;
import jlsm.table.UpdateMode;

import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import java.io.IOException;
import java.lang.foreign.MemorySegment;
import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.util.Collections;
import java.util.Iterator;
import java.util.List;
import java.util.Optional;
import java.util.Set;
import java.util.concurrent.CompletableFuture;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Tests for {@link ClusteredTable} — partition-aware proxy that scatters queries
 * across remote partition owners and gathers results.
 */
final class ClusteredTableTest {

    private static final NodeAddress LOCAL = new NodeAddress("local", "localhost", 9001);
    private static final NodeAddress REMOTE_A = new NodeAddress("remote-a", "localhost", 9002);
    private static final NodeAddress REMOTE_B = new NodeAddress("remote-b", "localhost", 9003);
    private static final Instant NOW = Instant.parse("2026-03-20T00:00:00Z");
    private static final JlsmSchema SCHEMA = JlsmSchema.builder("test", 1)
            .field("id", FieldType.Primitive.STRING)
            .field("value", FieldType.Primitive.STRING)
            .build();
    private static final TableMetadata TABLE_META = new TableMetadata(
            "users", SCHEMA, NOW, TableMetadata.TableState.READY);

    private InJvmTransport localTransport;
    private InJvmTransport remoteATransport;
    private InJvmTransport remoteBTransport;
    private StubMembershipProtocol membership;
    private ClusteredTable table;

    @BeforeEach
    void setUp() {
        InJvmTransport.clearRegistry();
        localTransport = new InJvmTransport(LOCAL);
        remoteATransport = new InJvmTransport(REMOTE_A);
        remoteBTransport = new InJvmTransport(REMOTE_B);
        membership = new StubMembershipProtocol();

        // Set up a view with local and remote nodes alive
        membership.view = new MembershipView(1,
                Set.of(
                        new Member(LOCAL, MemberState.ALIVE, 0),
                        new Member(REMOTE_A, MemberState.ALIVE, 0),
                        new Member(REMOTE_B, MemberState.ALIVE, 0)
                ), NOW);

        table = new ClusteredTable(TABLE_META, localTransport, membership);
    }

    @AfterEach
    void tearDown() {
        table.close();
        localTransport.close();
        remoteATransport.close();
        remoteBTransport.close();
        InJvmTransport.clearRegistry();
    }

    // --- Constructor validation ---

    @Test
    void constructor_nullTableMetadata_throws() {
        assertThrows(NullPointerException.class, () ->
                new ClusteredTable(null, localTransport, membership));
    }

    @Test
    void constructor_nullTransport_throws() {
        assertThrows(NullPointerException.class, () ->
                new ClusteredTable(TABLE_META, null, membership));
    }

    @Test
    void constructor_nullMembership_throws() {
        assertThrows(NullPointerException.class, () ->
                new ClusteredTable(TABLE_META, localTransport, null));
    }

    // --- metadata() ---

    @Test
    void metadata_returnsConfiguredMetadata() {
        assertEquals(TABLE_META, table.metadata());
    }

    // --- CRUD delegation ---

    @Test
    void create_sendsToTransport() throws IOException {
        // Register a success handler on remote
        registerSuccessHandler(remoteATransport);
        registerSuccessHandler(remoteBTransport);

        final JlsmDocument doc = JlsmDocument.of(SCHEMA, "id", "key1", "value", "val1");
        // This should route the write to the appropriate partition owner
        assertDoesNotThrow(() -> table.create("key1", doc));
    }

    @Test
    void get_returnsResultFromRemote() throws IOException {
        registerSuccessHandler(remoteATransport);
        registerSuccessHandler(remoteBTransport);

        final Optional<JlsmDocument> result = table.get("key1");
        assertNotNull(result);
    }

    @Test
    void update_routesToOwner() throws IOException {
        registerSuccessHandler(remoteATransport);
        registerSuccessHandler(remoteBTransport);

        final JlsmDocument doc = JlsmDocument.of(SCHEMA, "id", "key1", "value", "updated");
        assertDoesNotThrow(() -> table.update("key1", doc, UpdateMode.REPLACE));
    }

    @Test
    void delete_routesToOwner() throws IOException {
        registerSuccessHandler(remoteATransport);
        registerSuccessHandler(remoteBTransport);

        assertDoesNotThrow(() -> table.delete("key1"));
    }

    // --- scan() ---

    @Test
    void scan_returnsIterator() throws IOException {
        registerSuccessHandler(remoteATransport);
        registerSuccessHandler(remoteBTransport);

        final Iterator<TableEntry<String>> it = table.scan("a", "z");
        assertNotNull(it);
    }

    // --- Partial results ---

    @Test
    void partialResult_whenNodeUnavailable_returnsPartialMetadata() throws IOException {
        // Close one remote transport to make it unreachable
        remoteATransport.close();
        registerSuccessHandler(remoteBTransport);

        // The table should still return results from available nodes
        // and report partial results
        try {
            final Iterator<TableEntry<String>> it = table.scan("a", "z");
            // After a scan with unavailable partitions, lastPartialResultMetadata should be non-null
            final PartialResultMetadata partial = table.lastPartialResultMetadata();
            if (partial != null) {
                assertFalse(partial.isComplete());
            }
        } catch (IOException e) {
            // Acceptable if the implementation throws on partial failure
        }
    }

    @Test
    void lastPartialResultMetadata_afterCompleteQuery_isComplete() throws IOException {
        registerSuccessHandler(remoteATransport);
        registerSuccessHandler(remoteBTransport);

        try {
            table.scan("a", "z");
            final PartialResultMetadata partial = table.lastPartialResultMetadata();
            if (partial != null) {
                assertTrue(partial.isComplete());
            }
        } catch (UnsupportedOperationException e) {
            // Acceptable during initial implementation
        }
    }

    // --- close() ---

    @Test
    void close_isIdempotent() {
        table.close();
        assertDoesNotThrow(table::close);
    }

    // --- Helper methods ---

    private static void registerSuccessHandler(InJvmTransport transport) {
        transport.registerHandler(MessageType.QUERY_REQUEST, (sender, msg) -> {
            final Message response = new Message(
                    MessageType.QUERY_RESPONSE,
                    new NodeAddress(transport.toString(), "localhost", 9999),
                    msg.sequenceNumber(),
                    new byte[0]);
            return CompletableFuture.completedFuture(response);
        });
    }

    /**
     * Stub MembershipProtocol for testing.
     */
    private static final class StubMembershipProtocol implements MembershipProtocol {
        volatile MembershipView view = new MembershipView(0, Set.of(), NOW);

        @Override
        public void start(List<NodeAddress> seeds) {
        }

        @Override
        public MembershipView currentView() {
            return view;
        }

        @Override
        public void addListener(MembershipListener listener) {
        }

        @Override
        public void leave() {
        }

        @Override
        public void close() {
        }
    }
}

