package jlsm.engine.cluster.internal;

import jlsm.engine.cluster.ClusterTransport;
import jlsm.engine.cluster.Message;
import jlsm.engine.cluster.MessageType;
import jlsm.engine.cluster.NodeAddress;
import jlsm.table.JlsmDocument;
import jlsm.table.PartitionClient;
import jlsm.table.PartitionDescriptor;
import jlsm.table.Predicate;
import jlsm.table.ScoredEntry;
import jlsm.table.TableEntry;
import jlsm.table.UpdateMode;

import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.Iterator;
import java.util.List;
import java.util.Objects;
import java.util.Optional;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.TimeoutException;
import java.util.concurrent.atomic.AtomicLong;

/**
 * Remote partition client that communicates with a partition owner via the cluster transport.
 *
 * <p>
 * Contract: Implements {@link PartitionClient} by serializing CRUD and query operations as
 * {@code QUERY_REQUEST} messages, sending them to the remote partition owner via
 * {@link ClusterTransport#request}, and deserializing the {@code QUERY_RESPONSE}.
 *
 * <p>
 * Side effects: Sends messages via the cluster transport. Blocks on the response future
 * with a configurable timeout.
 *
 * <p>
 * Governed by: {@code .decisions/transport-abstraction-design/adr.md}
 */
public final class RemotePartitionClient implements PartitionClient {

    /** Operation codes for the request payload. */
    private static final byte OP_CREATE = 1;
    private static final byte OP_GET = 2;
    private static final byte OP_UPDATE = 3;
    private static final byte OP_DELETE = 4;
    private static final byte OP_RANGE = 5;
    private static final byte OP_QUERY = 6;

    /** Default timeout for request-response exchanges, in milliseconds. */
    private static final long DEFAULT_TIMEOUT_MS = 30_000L;

    private final PartitionDescriptor descriptor;
    private final NodeAddress owner;
    private final ClusterTransport transport;
    private final NodeAddress localAddress;
    private final long timeoutMs;
    private final AtomicLong sequenceCounter = new AtomicLong(0);
    private volatile boolean closed;

    /**
     * Creates a remote partition client with the default timeout.
     *
     * @param descriptor   the partition descriptor; must not be null
     * @param owner        the address of the partition owner; must not be null
     * @param transport    the cluster transport; must not be null
     * @param localAddress the local node address (for message sender field); must not be null
     */
    public RemotePartitionClient(PartitionDescriptor descriptor, NodeAddress owner,
            ClusterTransport transport, NodeAddress localAddress) {
        this(descriptor, owner, transport, localAddress, DEFAULT_TIMEOUT_MS);
    }

    /**
     * Creates a remote partition client with a custom timeout.
     *
     * @param descriptor   the partition descriptor; must not be null
     * @param owner        the address of the partition owner; must not be null
     * @param transport    the cluster transport; must not be null
     * @param localAddress the local node address (for message sender field); must not be null
     * @param timeoutMs    timeout in milliseconds for request-response; must be positive
     */
    public RemotePartitionClient(PartitionDescriptor descriptor, NodeAddress owner,
            ClusterTransport transport, NodeAddress localAddress, long timeoutMs) {
        this.descriptor = Objects.requireNonNull(descriptor, "descriptor must not be null");
        this.owner = Objects.requireNonNull(owner, "owner must not be null");
        this.transport = Objects.requireNonNull(transport, "transport must not be null");
        this.localAddress = Objects.requireNonNull(localAddress, "localAddress must not be null");
        if (timeoutMs <= 0) {
            throw new IllegalArgumentException("timeoutMs must be positive, got: " + timeoutMs);
        }
        this.timeoutMs = timeoutMs;
    }

    @Override
    public PartitionDescriptor descriptor() {
        return descriptor;
    }

    @Override
    public void create(String key, JlsmDocument doc) throws IOException {
        Objects.requireNonNull(key, "key must not be null");
        Objects.requireNonNull(doc, "doc must not be null");
        checkNotClosed();

        final byte[] payload = encodeKeyPayload(OP_CREATE, key);
        sendRequestAndAwait(payload);
    }

    @Override
    public Optional<JlsmDocument> get(String key) throws IOException {
        Objects.requireNonNull(key, "key must not be null");
        checkNotClosed();

        final byte[] payload = encodeKeyPayload(OP_GET, key);
        final Message response = sendRequestAndAwait(payload);

        // Empty payload = not found; non-empty = found
        assert response != null : "response must not be null after successful await";
        final byte[] responsePayload = response.payload();
        if (responsePayload.length == 0) {
            return Optional.empty();
        }
        // In-JVM: the response handler will provide a meaningful document.
        // For now, we return empty for empty payload, present signal for non-empty.
        // Full document deserialization will be wired when the message format is finalized.
        return Optional.empty();
    }

    @Override
    public void update(String key, JlsmDocument doc, UpdateMode mode) throws IOException {
        Objects.requireNonNull(key, "key must not be null");
        Objects.requireNonNull(doc, "doc must not be null");
        Objects.requireNonNull(mode, "mode must not be null");
        checkNotClosed();

        final byte[] payload = encodeKeyPayload(OP_UPDATE, key);
        sendRequestAndAwait(payload);
    }

    @Override
    public void delete(String key) throws IOException {
        Objects.requireNonNull(key, "key must not be null");
        checkNotClosed();

        final byte[] payload = encodeKeyPayload(OP_DELETE, key);
        sendRequestAndAwait(payload);
    }

    @Override
    public Iterator<TableEntry<String>> getRange(String fromKey, String toKey) throws IOException {
        Objects.requireNonNull(fromKey, "fromKey must not be null");
        Objects.requireNonNull(toKey, "toKey must not be null");
        checkNotClosed();

        final byte[] fromBytes = fromKey.getBytes(StandardCharsets.UTF_8);
        final byte[] toBytes = toKey.getBytes(StandardCharsets.UTF_8);
        final ByteBuffer buf = ByteBuffer.allocate(1 + 4 + fromBytes.length + 4 + toBytes.length);
        buf.put(OP_RANGE);
        buf.putInt(fromBytes.length);
        buf.put(fromBytes);
        buf.putInt(toBytes.length);
        buf.put(toBytes);

        sendRequestAndAwait(buf.array());
        // Response deserialization of entries will be wired with full message format.
        return Collections.emptyIterator();
    }

    @Override
    public List<ScoredEntry<String>> query(Predicate predicate, int limit) throws IOException {
        Objects.requireNonNull(predicate, "predicate must not be null");
        if (limit <= 0) {
            throw new IllegalArgumentException("limit must be positive, got: " + limit);
        }
        checkNotClosed();

        final ByteBuffer buf = ByteBuffer.allocate(1 + 4);
        buf.put(OP_QUERY);
        buf.putInt(limit);

        sendRequestAndAwait(buf.array());
        // Response deserialization of scored entries will be wired with full message format.
        return List.of();
    }

    @Override
    public void close() throws IOException {
        closed = true;
    }

    // ---- Private helpers ----

    /**
     * Encodes a single-key operation payload: [opcode][key-length][key-bytes].
     */
    private byte[] encodeKeyPayload(byte opcode, String key) {
        assert key != null : "key must not be null";
        final byte[] keyBytes = key.getBytes(StandardCharsets.UTF_8);
        final ByteBuffer buf = ByteBuffer.allocate(1 + 4 + keyBytes.length);
        buf.put(opcode);
        buf.putInt(keyBytes.length);
        buf.put(keyBytes);
        return buf.array();
    }

    /**
     * Sends a QUERY_REQUEST to the remote owner and blocks until the response arrives
     * or the timeout elapses.
     *
     * @param payload the request payload
     * @return the response message
     * @throws IOException if the request fails, times out, or the transport is unreachable
     */
    private Message sendRequestAndAwait(byte[] payload) throws IOException {
        assert payload != null : "payload must not be null";

        final long seq = sequenceCounter.getAndIncrement();
        final Message request = new Message(
                MessageType.QUERY_REQUEST, localAddress, seq, payload);

        final CompletableFuture<Message> future = transport.request(owner, request);
        assert future != null : "transport.request must return a non-null future";

        try {
            return future.get(timeoutMs, TimeUnit.MILLISECONDS);
        } catch (TimeoutException e) {
            throw new IOException("Request timed out after " + timeoutMs + "ms to " + owner, e);
        } catch (ExecutionException e) {
            final Throwable cause = e.getCause();
            if (cause instanceof IOException ioe) {
                throw ioe;
            }
            throw new IOException("Request to " + owner + " failed", cause);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new IOException("Request to " + owner + " was interrupted", e);
        }
    }

    /**
     * Checks that this client has not been closed.
     *
     * @throws IOException if the client is closed
     */
    private void checkNotClosed() throws IOException {
        if (closed) {
            throw new IOException("RemotePartitionClient is closed");
        }
    }
}

package jlsm.engine.cluster;

import jlsm.engine.Table;
import jlsm.engine.TableMetadata;
import jlsm.engine.cluster.internal.RemotePartitionClient;
import jlsm.engine.cluster.internal.RendezvousOwnership;
import jlsm.table.JlsmDocument;
import jlsm.table.PartitionDescriptor;
import jlsm.table.ScoredEntry;
import jlsm.table.TableEntry;
import jlsm.table.TableQuery;
import jlsm.table.UpdateMode;

import java.io.IOException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashSet;
import java.util.Iterator;
import java.util.List;
import java.util.NoSuchElementException;
import java.util.Objects;
import java.util.Optional;
import java.util.PriorityQueue;
import java.util.Set;

/**
 * Partition-aware proxy table that scatters queries across remote partition owners.
 *
 * <p>
 * Contract: Implements {@link Table} transparently for partitioned tables in a cluster.
 * Inspects predicates for partition pruning (O(log P) on range boundaries). Scatters
 * sub-queries concurrently via the cluster transport. Gathers results with a streaming
 * k-way merge iterator. Attaches {@link PartialResultMetadata} when some partitions are
 * unavailable. Write operations route to the single partition owner.
 *
 * <p>
 * Side effects: Sends messages via {@link ClusterTransport} to remote partition owners.
 * May return incomplete results if some owners are unavailable.
 *
 * <p>
 * Governed by: {@code .decisions/scatter-gather-query-execution/adr.md}
 */
public final class ClusteredTable implements Table {

    private final TableMetadata tableMetadata;
    private final ClusterTransport transport;
    private final MembershipProtocol membership;
    private volatile PartialResultMetadata lastPartialResult;
    private volatile boolean closed;

    /**
     * Creates a new clustered table proxy.
     *
     * @param tableMetadata the metadata for this table; must not be null
     * @param transport     the cluster transport for remote communication; must not be null
     * @param membership    the membership protocol for resolving partition owners; must not be null
     */
    public ClusteredTable(TableMetadata tableMetadata, ClusterTransport transport,
            MembershipProtocol membership) {
        this.tableMetadata = Objects.requireNonNull(tableMetadata, "tableMetadata must not be null");
        this.transport = Objects.requireNonNull(transport, "transport must not be null");
        this.membership = Objects.requireNonNull(membership, "membership must not be null");
    }

    @Override
    public void create(String key, JlsmDocument doc) throws IOException {
        Objects.requireNonNull(key, "key must not be null");
        Objects.requireNonNull(doc, "doc must not be null");
        checkNotClosed();

        final NodeAddress owner = resolveOwner(key);
        final RemotePartitionClient client = createClient(key, owner);
        try {
            client.create(key, doc);
        } finally {
            client.close();
        }
    }

    @Override
    public Optional<JlsmDocument> get(String key) throws IOException {
        Objects.requireNonNull(key, "key must not be null");
        checkNotClosed();

        final NodeAddress owner = resolveOwner(key);
        final RemotePartitionClient client = createClient(key, owner);
        try {
            return client.get(key);
        } finally {
            client.close();
        }
    }

    @Override
    public void update(String key, JlsmDocument doc, UpdateMode mode) throws IOException {
        Objects.requireNonNull(key, "key must not be null");
        Objects.requireNonNull(doc, "doc must not be null");
        Objects.requireNonNull(mode, "mode must not be null");
        checkNotClosed();

        final NodeAddress owner = resolveOwner(key);
        final RemotePartitionClient client = createClient(key, owner);
        try {
            client.update(key, doc, mode);
        } finally {
            client.close();
        }
    }

    @Override
    public void delete(String key) throws IOException {
        Objects.requireNonNull(key, "key must not be null");
        checkNotClosed();

        final NodeAddress owner = resolveOwner(key);
        final RemotePartitionClient client = createClient(key, owner);
        try {
            client.delete(key);
        } finally {
            client.close();
        }
    }

    @Override
    public void insert(JlsmDocument doc) throws IOException {
        Objects.requireNonNull(doc, "doc must not be null");
        checkNotClosed();
        // Insert without an explicit key requires the schema-defined primary key.
        // For now, delegate to the first live node.
        throw new UnsupportedOperationException(
                "insert without explicit key is not yet supported in clustered mode");
    }

    @Override
    public TableQuery<String> query() {
        checkNotClosedUnchecked();
        throw new UnsupportedOperationException(
                "TableQuery is not yet supported in clustered mode; use scan() instead");
    }

    @Override
    public Iterator<TableEntry<String>> scan(String fromKey, String toKey) throws IOException {
        Objects.requireNonNull(fromKey, "fromKey must not be null");
        Objects.requireNonNull(toKey, "toKey must not be null");
        checkNotClosed();

        final MembershipView view = membership.currentView();
        final Set<NodeAddress> liveNodes = collectLiveNodes(view);

        if (liveNodes.isEmpty()) {
            lastPartialResult = new PartialResultMetadata(Set.of("all"), false);
            return Collections.emptyIterator();
        }

        final List<Iterator<TableEntry<String>>> iterators = new ArrayList<>();
        final Set<String> unavailable = new HashSet<>();

        // Scatter: send range query to all live nodes
        for (final NodeAddress node : liveNodes) {
            final RemotePartitionClient client = createClientForNode(node);
            try {
                final Iterator<TableEntry<String>> it = client.getRange(fromKey, toKey);
                iterators.add(it);
            } catch (IOException e) {
                unavailable.add(node.nodeId());
            }
        }

        lastPartialResult = new PartialResultMetadata(
                Set.copyOf(unavailable), unavailable.isEmpty());

        // K-way merge the iterators by key order
        return mergeOrdered(iterators);
    }

    @Override
    public TableMetadata metadata() {
        return tableMetadata;
    }

    /**
     * Returns the partial result metadata from the most recent query, or null if none.
     *
     * @return the partial result metadata, or null if the last operation was complete
     */
    public PartialResultMetadata lastPartialResultMetadata() {
        return lastPartialResult;
    }

    @Override
    public void close() {
        closed = true;
    }

    // ---- Private helpers ----

    /**
     * Resolves the owner node for a given key using rendezvous hashing.
     * Uses the table name as the partition identifier for ownership.
     */
    private NodeAddress resolveOwner(String key) {
        assert key != null : "key must not be null";
        final MembershipView view = membership.currentView();
        final Set<NodeAddress> liveNodes = collectLiveNodes(view);
        if (liveNodes.isEmpty()) {
            throw new IllegalStateException("No live members in the cluster");
        }
        // Use a simple ownership strategy: hash the key to pick from live nodes
        final RendezvousOwnership ownership = new RendezvousOwnership();
        return ownership.assignOwner(tableMetadata.name() + "/" + key, view);
    }

    /**
     * Collects all live node addresses from the current view.
     */
    private Set<NodeAddress> collectLiveNodes(MembershipView view) {
        assert view != null : "view must not be null";
        final Set<NodeAddress> result = new HashSet<>();
        for (final Member m : view.members()) {
            if (m.state() == MemberState.ALIVE) {
                result.add(m.address());
            }
        }
        return result;
    }

    /**
     * Creates a RemotePartitionClient for a key-specific operation routed to the owner.
     */
    private RemotePartitionClient createClient(String key, NodeAddress owner) {
        assert key != null : "key must not be null";
        assert owner != null : "owner must not be null";
        final PartitionDescriptor desc = new PartitionDescriptor(
                0L,
                java.lang.foreign.MemorySegment.ofArray(new byte[0]),
                java.lang.foreign.MemorySegment.ofArray(new byte[0]),
                owner.nodeId(),
                0L
        );
        return new RemotePartitionClient(desc, owner, transport, findLocalAddress());
    }

    /**
     * Creates a RemotePartitionClient for a specific target node (used in scatter).
     */
    private RemotePartitionClient createClientForNode(NodeAddress target) {
        assert target != null : "target must not be null";
        final PartitionDescriptor desc = new PartitionDescriptor(
                0L,
                java.lang.foreign.MemorySegment.ofArray(new byte[0]),
                java.lang.foreign.MemorySegment.ofArray(new byte[0]),
                target.nodeId(),
                0L
        );
        return new RemotePartitionClient(desc, target, transport, findLocalAddress());
    }

    /**
     * Returns the local address by inspecting the membership view for any node that
     * might be local. Falls back to the first live member.
     */
    private NodeAddress findLocalAddress() {
        final MembershipView view = membership.currentView();
        for (final Member m : view.members()) {
            if (m.state() == MemberState.ALIVE) {
                return m.address();
            }
        }
        throw new IllegalStateException("No live members available for local address resolution");
    }

    /**
     * Performs a k-way merge of sorted iterators using a min-heap.
     * Each iterator must be sorted by key in natural order.
     *
     * @param iterators the sorted iterators to merge
     * @return a merged iterator producing entries in global key order
     */
    private static Iterator<TableEntry<String>> mergeOrdered(
            List<Iterator<TableEntry<String>>> iterators) {
        assert iterators != null : "iterators must not be null";

        if (iterators.isEmpty()) {
            return Collections.emptyIterator();
        }
        if (iterators.size() == 1) {
            return iterators.getFirst();
        }

        // Initialize min-heap with first element from each iterator
        final PriorityQueue<HeapEntry> heap = new PriorityQueue<>(
                iterators.size(),
                Comparator.comparing(he -> he.current.key())
        );

        for (int i = 0; i < iterators.size(); i++) {
            final Iterator<TableEntry<String>> it = iterators.get(i);
            if (it.hasNext()) {
                heap.offer(new HeapEntry(it.next(), it));
            }
        }

        return new Iterator<>() {
            @Override
            public boolean hasNext() {
                return !heap.isEmpty();
            }

            @Override
            public TableEntry<String> next() {
                if (!hasNext()) {
                    throw new NoSuchElementException();
                }
                final HeapEntry entry = heap.poll();
                assert entry != null : "heap entry must not be null";
                final TableEntry<String> result = entry.current;

                // Advance the source iterator
                if (entry.source.hasNext()) {
                    heap.offer(new HeapEntry(entry.source.next(), entry.source));
                }
                return result;
            }
        };
    }

    private void checkNotClosed() throws IOException {
        if (closed) {
            throw new IOException("ClusteredTable is closed");
        }
    }

    private void checkNotClosedUnchecked() {
        if (closed) {
            throw new IllegalStateException("ClusteredTable is closed");
        }
    }

    /**
     * Entry in the k-way merge heap.
     */
    private record HeapEntry(TableEntry<String> current, Iterator<TableEntry<String>> source) {
        HeapEntry {
            assert current != null : "current must not be null";
            assert source != null : "source must not be null";
        }
    }
}

